mapper.select:
SELECT Q.QNA_ID AS qnaId, Q.PRODUCT_ID AS productId, Q.USER_ID AS userId, Q.OPTION_NAME AS optionName, Q.QUESTION_CONTENT AS questionContent, Q.ANSWER_CONTENT AS answerContent, Q.STATUS AS status, Q.SECRET_YN AS secretYn, DATE_FORMAT(Q.CREATED_AT, '%Y-%m-%d %H:%i') AS createdAt, DATE_FORMAT(Q.ANSWERED_AT, '%Y-%m-%d %H:%i') AS answeredAt,
COALESCE(U.NICKNAME, Q.USER_ID) AS nickname, U.PROFILE_IMG_URL AS profileImgUrl
FROM PRODUCT_QNA Q LEFT JOIN USER U ON Q.USER_ID = U.USER_ID WHERE Q.PRODUCT_ID = #{productId}
AND Q.QUESTION_CONTENT LIKE CONCAT('%', #{keyword}, '%')
ORDER BY Q.CREATED_AT DESC LIMIT #{offset}, #{pageSize}

