mapper.select:
SELECT Q.QNA_ID AS qnaId, Q.PRODUCT_ID AS productId, Q.USER_ID AS userId, Q.OPTION_NAME AS optionName, Q.QUESTION_CONTENT AS questionContent, Q.ANSWER_CONTENT AS answerContent, Q.STATUS AS status, Q.SECRET_YN AS secretYn, DATE_FORMAT(Q.CREATED_AT, '%Y-%m-%d %H:%i') AS createdAt, DATE_FORMAT(Q.ANSWERED_AT, '%Y-%m-%d %H:%i') AS answeredAt, COALESCE(U.NICKNAME, Q.USER_ID) AS nickname, P.PRODUCT_NAME AS productName FROM PRODUCT_QNA Q LEFT JOIN USER U ON Q.USER_ID = U.USER_ID LEFT JOIN PRODUCT P ON Q.PRODUCT_ID = P.PRODUCT_ID
WHERE Q.STATUS = #{status}
ORDER BY Q.CREATED_AT DESC
